import {supplierComparisonAction} from "@/lib/actions/supplier-comparisons";
import {PageHeader} from "@/components/layout/page-header";
export default async function SupplierComparisonDatabase({searchParams}:{searchParams:Promise<Record<string,string|string[]|undefined>>}){
  const params=await searchParams,search=typeof params.q==="string"?params.q.slice(0,80):"",sort=params.sort==="title"?"title":"newest",raw=Number(params.page??1),page=Number.isSafeInteger(raw)&&raw>0?Math.min(raw,10000):1;
  const result=await supplierComparisonAction({command:"requests.list",page,search,sort});
  const href=(next:number)=>`/vendors/comparisons/database?${new URLSearchParams({q:search,sort,page:String(next)})}`;
  return <div className="space-y-5"><PageHeader title="Purchase comparison database" description="Ten requests per page, with literal search and server-side sorting."/><form className="flex flex-wrap gap-3"><input aria-label="Search purchase comparisons" className="form-input max-w-md" name="q" defaultValue={search} placeholder="Requirement or specification"/><select aria-label="Sort comparisons" className="form-input max-w-40" name="sort" defaultValue={sort}><option value="newest">Newest</option><option value="title">Title</option></select><button className="rounded-xl bg-charcoal px-4 py-2 font-bold text-white">Search</button></form>{result.success&&result.kind==="directory"?<><div className="overflow-x-auto rounded-2xl border bg-white"><table className="industrial-table"><thead><tr><th>Requirement</th><th>Specification</th><th>Quantity</th><th>Required by</th></tr></thead><tbody>{result.data.items.map(item=><tr key={item.id}><td><a className="font-bold underline" href={`/vendors/comparisons/${item.id}`}>{item.title}</a></td><td>{item.specification}</td><td>{item.quantity} {item.unit}</td><td>{item.required_by||"Not captured"}</td></tr>)}</tbody></table></div>{!result.data.items.length?<p>No matching purchase comparisons.</p>:null}<div className="flex gap-4">{page>1?<a className="underline" href={href(page-1)}>Previous</a>:null}<span>Page {page}</span>{result.data.items.length===10?<a className="underline" href={href(page+1)}>Next</a>:null}</div></>:<p role="alert">{result.success?"Unavailable":result.error}</p>}</div>;
}
